function rngFactory(seed){ var s=(seed>>>0)||1; return function(){ s=(s*1664525+1013904223)>>>0; return s/4294967296; }; }

var PRO=['鸡胸肉','三文鱼','豆腐','牛肉','虾仁','鸡蛋','鹰嘴豆','鲈鱼'];
var VEG=['西兰花','番茄','菠菜','彩椒','芦笋','蘑菇','南瓜','秋葵'];
var MTD=['清炒','慢炖','香煎','凉拌','烤箱烤','红烧','蒸','油醋渍'];
var STY=['低卡','高蛋白','地中海风','家常','快手','宴客'];
function pick(a,r){return a[Math.floor(r()*a.length)];}
function generate(seed){ var r=rngFactory(seed); return pick(STY,r)+pick(PRO,r)+pick(MTD,r)+pick(VEG,r); }
var EXPORTS={generate:generate};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.RecipeIdeaForgePure = EXPORTS; }
